const moveGeoAnswer = (question, target, reforge = false) => {
  const item = reforge ? question.reforge : question;
  const current = item.correct;
  if (current !== target) [item.options[current], item.options[target]] = [item.options[target], item.options[current]];
  item.correct = target;
};
for (const [bankId, [idPattern, plan, reforgePlan]] of Object.entries(geo640BalancePlans)) {
  const questions = BANKS[bankId].questions.filter(question => idPattern.test(question.id));
  questions.forEach((question, index) => {
    moveGeoAnswer(question, plan[index]);
    moveGeoAnswer(question, reforgePlan[index], true);
  });
}
