const moveGcseScienceAnswer = (question, target, reforge = false) => {
  const item = reforge ? question.reforge : question;
  if (item.correct !== target) [item.options[item.correct], item.options[target]] = [item.options[target], item.options[item.correct]];
  item.correct = target;
};
const gcseScienceAnswerPlans = {
  "GCSE-SCI-BIO-1": ["ABCDABCDABCD", "CDABCDABCDAB"],
  "GCSE-SCI-CHEM-1": ["BCDABCDABCDA", "DABCDABCDABC"],
  "GCSE-SCI-PHYS-1": ["CDABCDABCDAB", "ABCDABCDABCD"]
};
for (const [bankId, [basePlan, reforgePlan]] of Object.entries(gcseScienceAnswerPlans)) {
  BANKS[bankId].questions.forEach((question, index) => {
    moveGcseScienceAnswer(question, basePlan[index]);
    moveGcseScienceAnswer(question, reforgePlan[index], true);
  });
}
// Keep options comparable in length after answer-position balancing. The
